// CyberLab catalog part 3: per-lesson practical assessments, checkpoints and
// level finals (Levels 0–3 fully authored), diagnostic, skill assessments,
// knowledge base, tracks, SOC events, code library, briefing snapshot,
// pentest workflow, threat sources, templates, and the Cloudflare deploy steps.

import type { QuizQ } from "./catalog";

export type Practical = { task: string; options: string[]; answer: number; explain: string; hint: string };

// One validated practical task per published lesson (Layer 1 requirement).
export const PRACTICALS: Record<string, Practical> = {
  "l0-what-is-cybersecurity": { task: "A photo app lets anyone who finds the URL view any user's private photos. Which control fixes the root problem?", options: ["Longer URLs", "Server-side authorization checks on every photo request", "A warning banner", "Faster servers"], answer: 1, explain: "Unguessable links are not access control. The server must verify the requester owns (or is shared) each photo.", hint: "Think A01: authentication vs authorization." },
  "l0-ethics-law": { task: "A bug-bounty program's scope lists *.shop.example.com but excludes payments.shop.example.com. You find a flaw on the payments subdomain. Correct action?", options: ["Test it fully — it's a subdomain", "Stop: it is explicitly out of scope; report only via the program's out-of-scope guidance if offered", "Publish it", "Sell it"], answer: 1, explain: "Exclusions are part of authorization. Out-of-scope findings are handled only as the program directs.", hint: "Scope is the authorization document — including its exclusions." },
  "l0-teams-roles": { task: "After a lab phishing simulation, the SOC missed the alert. The purple-team next step is:", options: ["Hide the result from management", "Replay the simulation while watching the telemetry, find the gap, write/improve the detection, and re-test", "Blame the night shift", "Buy a new tool"], answer: 1, explain: "Purple = simulate → observe → improve detection → re-validate, together.", hint: "It is a loop with both teams in the room." },
  "l1-inside-computer": { task: "A machine profile shows: MBR disk, Secure Boot unavailable, TPM absent. The boot mode is almost certainly:", options: ["UEFI with Secure Boot", "Legacy BIOS", "UEFI without TPM", "Network boot"], answer: 1, explain: "MBR + no Secure Boot option + no TPM is the legacy BIOS signature (compare the Level 1 lab profile, which was GPT/UEFI).", hint: "Pair the partition style with the firmware features." },
  "l1-processes-memory": { task: "Process tree: OUTLOOK.EXE → cmd.exe → powershell.exe -enc (long encoded string). Verdict?", options: ["Normal email behaviour", "Suspicious: an office app spawning shells is a classic malicious-document pattern — investigate", "A Windows update", "Proof of a virus with no further checks needed"], answer: 1, explain: "Parent/child anomaly + encoded PowerShell = escalate and investigate (the Level 20 Sigma rule targets exactly this family). Suspicion with evidence, not a verdict without it.", hint: "Name + path + parent + behavior — judge all four." },
  "l1-files-permissions": { task: "Fix this line for a private SSH key: -rw-rw-rw- id_rsa. The correct command is:", options: ["chmod 777 id_rsa", "chmod 600 id_rsa", "chmod 444 id_rsa", "chown root id_rsa"], answer: 1, explain: "600 = owner read/write only. SSH refuses group/world-accessible private keys.", hint: "Owner rw, everyone else nothing." },
  "l2-osi-tcpip": { task: "Users report: 'We can open the intranet by IP (http://10.0.0.15) but the name intranet.local never loads.' First test?", options: ["Replace all cables", "Check DNS resolution for intranet.local (dig/nslookup) — transport and app already proven by IP", "Reinstall browsers", "Change everyone's IP"], answer: 1, explain: "Layer localization: IP works → L1–L4 and the app are fine; name resolution is the failing service.", hint: "What does a name add that an IP does not need?" },
  "l2-subnetting-dns": { task: "A lab PC is configured 192.168.10.70/26 in the 'users' subnet 192.168.10.0/26. What is wrong?", options: ["Nothing", ".70 belongs to the SECOND /26 (.64–.127) — the servers subnet; the PC sits in the wrong segment", "The mask should be /8", "DNS is missing"], answer: 1, explain: "/26 blocks start at .0, .64, .128, .192. .70 is in block 2 — a segmentation error with firewall consequences.", hint: "List the four block starts first." },
  "l2-network-tools": { task: "Choose the command: 'List what is listening on this Linux box, with the owning processes.'", options: ["ping -tlnp", "ss -tlnp", "dig listen", "traceroute --listen"], answer: 1, explain: "ss is the socket tool; -t (TCP) -l (listening) -n (numeric) -p (process).", hint: "Which tool from the lesson answers 'what is connected/listening'?" },
  "l3-linux-essentials": { task: "You need the number of failed SSH logins in /var/log/auth.log. Pick the pipeline:", options: ["cat /var/log/auth.log | delete Failed", "grep 'Failed password' /var/log/auth.log | wc -l", "ls -l /var/log | ping", "sudo rm /var/log/auth.log"], answer: 1, explain: "grep filters the pattern; wc -l counts the lines. Nothing is modified.", hint: "Filter, then count." },
  "l3-windows-admin": { task: "Task: 'Show the 10 most recent failed logons from the Security log.' Pick the cmdlet:", options: ["Get-Service -Id 4625", "Get-WinEvent -FilterHashtable @{LogName='Security'; Id=4625} -MaxEvents 10", "Get-Process 4625", "Set-WinEvent 4625"], answer: 1, explain: "Get-WinEvent with a FilterHashtable on LogName + Id 4625 (failed logon), capped with -MaxEvents.", hint: "4625 is an event ID — which cmdlet reads events?" },
  "l3-bash-scripting": { task: "Spot the dangerous bug:  file=$1  …  rm -rf $file  (no quotes, no check). The professional fix set is:", options: ["Run it as root", "Quote the variable, verify the path is non-empty and inside the intended directory, and print before deleting", "Add more -f flags", "Hide errors with 2>/dev/null"], answer: 1, explain: "Unquoted empty expansion turns rm -rf into a catastrophe class. Quote, validate, preview.", hint: "What happens when $file is empty or contains a space?" },
  "l4-python-security": { task: "Your parser must count 'Failed password' lines per IP from a 4 GB log. The correct structure is:", options: ["data = open(f).read(); then split everything in RAM", "Iterate lines with a with-block, take the token after 'from', count in a Counter", "Copy the log into a spreadsheet", "Use eval() on each line"], answer: 1, explain: "Streaming iteration + Counter keeps memory flat and code small — the lesson's pattern.", hint: "Memory first: 4 GB is the clue." },
  "l4-c-memory": { task: "Review: char buf[16]; strcpy(buf, argv[1]); — the finding and fix:", options: ["Fine; argv is trusted", "Unbounded copy into a 16-byte stack buffer (CWE-121 class); use a bounded copy tied to sizeof(buf) and validate length", "Needs more RAM", "Use a bigger monitor"], answer: 1, explain: "strcpy trusts the source length completely. Bounded APIs + length checks are the durable fix.", hint: "What limits the copy? Nothing — that's the bug." },
  "l4-javascript-browser": { task: "Fix the snippet: el.innerHTML = location.search.slice(6); — the safe version assigns to:", options: ["document.write", "el.textContent (value shown as inert text)", "el.outerHTML", "eval()"], answer: 1, explain: "innerHTML parses attacker-controlled markup; textContent never parses — the lesson's core rule.", hint: "Which sink never parses HTML?" },
  "l5-http-sessions": { task: "Write the hardened session cookie. Pick the correct Set-Cookie:", options: ["Set-Cookie: sid=abc; Path=/", "Set-Cookie: sid=abc; Path=/; HttpOnly; Secure; SameSite=Lax", "Set-Cookie: sid=abc; Domain=*.example.com; HttpOnly", "Set-Cookie: password=abc; HttpOnly"], answer: 1, explain: "All three flags, session ID (never the password), tight scope.", hint: "Three flags from the lesson, on the ID — not the credential." },
  "l6-crypto-basics": { task: "Design review: 'User passwords stored as MD5(password), no salt.' Your finding:", options: ["Acceptable for internal apps", "Critical: fast + unsalted hashes fall to GPU cracking and rainbow tables; migrate to Argon2id/bcrypt with per-user salt (rehash on next login)", "Fix by encrypting the MD5 values with ROT13", "Fix by hiding the table"], answer: 1, explain: "The lesson's standard: salt + slow memory-hard KDF, with a pragmatic migration path.", hint: "Two separate failures: speed and salt." },
  "l7-tool-methodology": { task: "Your scanner reports 'Critical: Apache 2.4.49 (vulnerable)' on a Debian host, banner-based. Before writing the finding you:", options: ["Report it as Critical immediately", "Verify the distro package version/changelog — Debian backports fixes; check installed patch level and validate safely in scope", "Run an exploit to confirm", "Delete the scan"], answer: 1, explain: "Banner ≠ patch state. Verification is the professional step that separates findings from noise.", hint: "What do distributions do to old version branches?" },
  "l8-access-control-sqli": { task: "Fix this handler: it returns invoice #id to any logged-in user. The complete fix is:", options: ["Make IDs UUIDs only", "Keep login check AND add: load invoice, compare invoice.owner_id to the session user, return 404 on mismatch + a two-account regression test", "Hide the button", "Add CAPTCHA"], answer: 1, explain: "Ownership check server-side per object, plus the regression test. UUIDs alone are not authorization.", hint: "Authentication asked 'who'; the fix asks 'whose'." },
  "l9-network-defense": { task: "Review this ruleset: (1) ALLOW any→server 443 (2) ALLOW any→server ANY (3) DENY all. The problem:", options: ["Rule 1 is too strict", "Rule 2 makes rule 1 (and the deny) pointless for the server — ANY from anywhere is a de-facto open server; remove or scope rule 2", "Rules must be alphabetical", "DENY should be first"], answer: 1, explain: "Top-down evaluation: rule 2 already permits everything to the server. Minimal, justified rules only.", hint: "Read top-down and ask what each rule adds." },
  "l12-reading-cve": { task: "Triage: CVE-A (CVSS 9.8, not in KEV, EPSS 0.01, product not in your inventory) vs CVE-B (CVSS 7.5, IN KEV, ransomware 'Known', confirmed on your internet-facing server). Patch order?", options: ["A first — higher CVSS", "B first — confirmed exploitation + confirmed exposure beats theoretical severity", "Neither; wait for vendor email", "Alphabetical"], answer: 1, explain: "KEV + exposure outranks raw CVSS. A gets scheduled by severity after B's clock.", hint: "Reality (KEV/exposure) vs theory (CVSS)." },
  "l16-android-basics": { task: "A release build's manifest shows android:debuggable=\"true\" and an exported provider with no permission. Your report's top two findings are:", options: ["Icon too large; name too long", "Debuggable release build + exported unprotected provider (data exposure) — both must be fixed before release", "Uses too many permissions (it requests one)", "No dark mode"], answer: 1, explain: "The lesson's findings, severity-ordered: production exposure first.", hint: "What would an attacker app on the same phone do with these?" },
  "l18-ir-forensics": { task: "A workstation is actively encrypting files (ransomware behavior). The one case where power-off/isolation order flips — your first move is:", options: ["Carefully collect RAM for an hour", "Isolate/disconnect immediately to stop spread and damage — destruction in progress outranks evidence niceties; document what you did and why", "Negotiate", "Format the disk"], answer: 1, explain: "Active destruction is the exception: stop the harm first, document the deviation.", hint: "The lesson named one exception to 'isolate, don't power off' — ongoing destruction." },
  "l20-detection-engineering": { task: "Improve this 'detection': block IP 203.0.113.44. The behavior-based upgrade is:", options: ["Block the whole /24", "Detect the BEHAVIOR the IP was used for (e.g. Office→PowerShell spawn, ATT&CK T1059.001) with a Sigma rule + FP notes, keep the IP as scoping context only", "Block the country", "Delete the logs"], answer: 1, explain: "IPs rotate in minutes; behaviors persist. Indicators scope; behaviors detect.", hint: "Pyramid of Pain: climb it." },
};

export type Checkpoint = {
  id: string; level: number; afterLessons: string[]; title: string; xp: number;
  quiz: QuizQ[]; practical: Practical; weakMap: string[]; // weakMap[i] = lesson id blamed for quiz question i
};
export type LevelFinal = {
  id: string; level: number; title: string; xp: number; badge: string; skillStep: string;
  quiz: QuizQ[]; practicals: Practical[]; written: { prompt: string; model: string };
};

