// ---------------- Pentest Workspace ----------------
export const PENTEST_STEPS: { title: string; detail: string }[] = [
  { title: "Authorization & scope", detail: "Written permission from the system owner: targets, techniques, window, exclusions, contacts. No document, no test." },
  { title: "Rules of engagement", detail: "Hours, rate limits, prohibited actions (e.g. no DoS), data-handling rules, stop conditions, escalation path." },
  { title: "Asset identification", detail: "Inventory in-scope hosts, apps, accounts, and APIs from provided documentation + passive sources." },
  { title: "Reconnaissance", detail: "Passive first: public records, published docs. Active probing only where the scope explicitly allows it." },
  { title: "Enumeration", detail: "Services, versions, endpoints, roles — on in-scope lab/authorized targets (your lab, localhost, training apps)." },
  { title: "Attack-surface mapping", detail: "Entry points, trust boundaries, auth flows, data flows — drawn before any testing." },
  { title: "Vulnerability assessment", detail: "Tool-assisted discovery (scoped) + manual review; every candidate is a lead, not a finding." },
  { title: "Controlled validation", detail: "Verify each lead minimally and safely in the authorized environment; record exact requests/commands." },
  { title: "Evidence collection", detail: "Timestamped requests/responses, screenshots, hashes; chain of custody for anything sensitive." },
  { title: "Impact analysis", detail: "What the verified issue actually enables, in business terms, with the preconditions stated." },
  { title: "Risk classification", detail: "Severity with rationale (CVSS where apt), likelihood context, and affected assets." },
  { title: "Remediation guidance", detail: "The durable fix pattern per finding, with the regression test that locks it." },
  { title: "Retesting", detail: "Re-run the exact validation after fixes; record pass/fail per finding." },
  { title: "Final reporting", detail: "Executive summary, methodology, findings with evidence, remediation, retest results — via the template below." },
];

